import sys, zipfile, re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "pr": "http://schemas.openxmlformats.org/package/2006/relationships",
}

def col_letter_to_index(letter):
    n = 0
    for ch in letter:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n

def index_to_col_letter(idx):
    s = ""
    while idx:
        idx, rem = divmod(idx - 1, 26)
        s = chr(ord("A") + rem) + s
    return s

path = "budget.xlsx"
try:
    z = zipfile.ZipFile(path)
except FileNotFoundError:
    print("ERROR: budget.xlsx not found")
    sys.exit(1)

names = z.namelist()
print("ZIP entries:", names)

# shared strings
shared = []
if "xl/sharedStrings.xml" in names:
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall("m:si", NS):
        texts = si.findall(".//m:t", NS)
        shared.append("".join(t.text or "" for t in texts))

# workbook sheet list
wbroot = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
relmap = {}
for rel in rels:
    rid = rel.get("Id")
    target = rel.get("Target")
    if target.startswith("/"):
        target = target.lstrip("/")
    else:
        target = "xl/" + target
    relmap[rid] = target

sheet_files = []
for sh in wbroot.findall(".//m:sheets/m:sheet", NS):
    rid = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
    sheet_files.append((sh.get("name"), relmap[rid]))
print("Sheets:", sheet_files)

def parse_sheet(xml_bytes):
    root = ET.fromstring(xml_bytes)
    rows = {}
    for c in root.iter("{%s}c" % NS["m"]):
        ref = c.get("r")
        t = c.get("t")
        v = c.find("m:v", NS)
        f = c.find("m:f", NS)
        isel = c.find("m:is", NS)
        raw = None
        if v is not None and v.text is not None:
            raw = v.text
        val = raw
        if t == "s" and raw is not None:
            val = shared[int(raw)]
        elif t == "inlineStr" and isel is not None:
            val = "".join(x.text or "" for x in isel.findall(".//m:t", NS))
        elif t == "str" and raw is not None:
            val = raw
        elif raw is not None:
            try:
                if re.fullmatch(r"-?\d+", raw):
                    val = int(raw)
                else:
                    val = float(raw)
            except ValueError:
                val = raw
        formula = f.text if f is not None else None
        rows[ref] = (val, formula)
    return rows

for sheet_name, target in sheet_files:
    print(f"\n=== Sheet: {sheet_name} ===")
    xml_bytes = z.read(target)
    cells = parse_sheet(xml_bytes)
    # sort by row, col
    def key(item):
        m = re.match(r"([A-Z]+)(\d+)", item[0])
        return (int(m.group(2)), col_letter_to_index(m.group(1)))
    for ref in sorted(cells, key=key):
        val, formula = cells[ref]
        extra = f"  [formula: {formula}]" if formula else ""
        print(f"{ref}: {val!r}{extra}")

